    "x": "Denkanker'in 4 sorusu: ne ölçülüyor, nasıl iletiliyor, kim/ne tepki veriyor, işlevsel olarak ne değişiyor. „Nasıl görünüyor?“ anatominin sorusudur, Denkanker'e ait değildir.",
    "xEn": "The 4 questions of the Denkanker: what is measured, how is it transmitted, who/what reacts, what changes functionally. 'What does it look like?' is a question of anatomy and does not belong to the Denkanker."
