    "x": "Lizozom hücrenin çöp sistemidir; eski ve yabancı maddeleri yıkar. Golgi paketler ve gönderir; düz ER zehir yıkımına yardım eder ama çöp sistemi değildir.",
    "xEn": "The lysosome is the cell's waste system; it breaks down old and foreign substances. The Golgi packages and ships; the smooth ER helps break down toxins but is not the waste system."
