    "x": "DNA planı porlardan çıkar, granüllü ER'deki ribozomda protein yapılır, Golgi paketler, vezikül zara taşır. Golgi üretimden önce gelemez; protein ribozomsuz düz ER'de değil, granüllü ER'de yapılır.",
    "xEn": "The DNA plan leaves through the pores, the protein is made at the ribosome on the rough ER, the Golgi packages it, a vesicle carries it to the membrane. The Golgi cannot come before production; protein is made on the rough ER, not on the smooth ER without ribosomes."
