    "x": "'Hareket sırtıma zarar verir' olumsuz bir düşüncedir (Kognition) → kronikleşme riski taşıyan sarı bayrak. Ciddi bir hastalık işareti olmadığı için kırmızı bayrak değildir.",
    "xEn": "'Movement harms my back' is a negative thought (Kognition) → a yellow flag with a risk of chronification. It is not a red flag because it is not a sign of serious disease."
