    "x": "Açık soru hastaya kendi anlatımı için alan bırakır. Kaza ve merdiven soruları evet/hayır ile cevaplanan kapalı sorulardır; 'Ağrınız var, değil mi?' cevabı önceden veren yönlendirici sorudur.",
    "xEn": "An open question leaves the patient room to tell it in their own words. The accident and stairs questions are closed questions answered with yes/no; 'You have pain, right?' is a leading question that gives the answer in advance."
