    "xEn": "Night sweats are a red flag (Minimalkonsens 7). Yellow flag areas: Kognitionen, Emotionen, Verhalten, Familie, Arbeitsplatz, Diagnostik/Behandlung, Ausgleich/Entschädigungsleistungen (compensation payments)."
