    "a": "Das Hüftgelenk (Articulatio coxae) ist die Verbindung zwischen Os coxae und Femur, ein Kugelgelenk bzw. Nussgelenk mit 3 Freiheitsgraden; das Acetabulum aus Os ilium, ischii und pubis trägt nur über die Facies lunata, die Fossa acetabuli ist mit Fett gefüllt. Die Kapsel wird durch die Bänderschraube aus Lig. iliofemorale, ischiofemorale und pubofemorale verstärkt, die alle die Extension hemmen. Die Muskeln gliedere ich nach Bewegungsrichtung: Flexion v. a. Iliopsoas, Extension Gluteus maximus und Hamstrings, Abduktion Gluteus medius/minimus und TFL, Adduktion die Adduktoren, Rotation die tiefen Außenrotatoren. Im Einbeinstand trägt die Hüfte nach Pauwels das 3–4-fache Körpergewicht; klinisch ist die Coxarthrose am häufigsten, die v. a. Innenrotation und Extension einschränkt und oft in einer H-TEP endet.",
