   {
    "de": "Training ist ein komplexer Handlungsprozess, der auf systematischer Planung, Ausführung und Evaluation basiert und nachhaltige Ziele in Sport, Prävention und Rehabilitation verfolgt (Hottenrott, 2020).",
    "tr": "Folyodaki sınav tanımı: antrenman, planlama, uygulama ve değerlendirmeye dayanan karmaşık bir eylem sürecidir; spor, önleme ve rehabilitasyonda kalıcı hedefler güder.",
    "en": "Exam definition from the slides: training is a complex process of action based on planning, execution and evaluation; it pursues lasting goals in sport, prevention and rehabilitation."
   },
   {
    "de": "Nach Hollmann und Hettinger ist Training die systematische Wiederholung gezielter überschwelliger Muskelanspannungen mit morphologischen und funktionellen Anpassungserscheinungen zum Zwecke der Leistungssteigerung.",
    "tr": "Klasik ek tanım: eşik üstü kas gerilimlerinin sistematik tekrarı; yapısal ve işlevsel uyum ile performans artışı amaçlanır.",
    "en": "Classic additional definition: systematic repetition of above-threshold muscle tensions; aims at structural and functional adaptation and increased performance."
   },
   {
    "de": "Die fünf motorischen Hauptbeanspruchungsformen sind Kraft, Ausdauer, Beweglichkeit, Koordination und Schnelligkeit.",
    "tr": "Beş temel motorik özellik: kuvvet, dayanıklılık, hareketlilik, koordinasyon, sürat.",
    "en": "Five basic motor abilities: strength, endurance, mobility, coordination, speed."
   },
   {
    "de": "In der Physiotherapie ist Kraft am wichtigsten, Schnelligkeit am wenigsten wichtig.",
    "tr": "Fizyoterapide öncelik kuvvettir; hastalar sprint yapmak zorunda olmadığı için sürat en az önemlidir.",
    "en": "In physiotherapy strength comes first; speed is the least important because patients do not have to sprint."
   },
   {
    "de": "Die Anpassung an Training findet nicht während, sondern nach dem Training in der Erholungsphase statt.",
    "tr": "Uyum antrenman sırasında değil, sonrasında dinlenme (rejenerasyon) evresinde oluşur; antrenman sırasında vücut sadece stres altındadır.",
    "en": "Adaptation happens not during training but afterwards, in the rest (regeneration) phase; during training the body is only under stress."
   },
   {
    "de": "Training ist zielgerichtet, planmäßig und systematisch.",
    "tr": "Zielgerichtet = kişinin hedefine yönelik; planmäßig = içerik ve yöntem önceden belirlenmiş; systematisch = adımlar birbirinin üzerine kurulu, düzenli ve sürekli.",
    "en": "Zielgerichtet = aimed at the person's goal; planmäßig = content and method decided in advance; systematisch = steps build on each other, regular and continuous."
   },
   {
    "de": "Beim Training ist der Patient aktiv und der Therapeut leitet an; bei passiven Techniken setzt der Therapeut den Reiz.",
    "tr": "Antrenmanda hasta aktiftir, terapist yönlendirir; pasif tekniklerde terapist aktiftir ve bunlar Trainingslehre konusu değildir.",
    "en": "In training the patient is active and the therapist guides; in passive techniques the therapist is active, and these are not part of Trainingslehre."
   },
   {
    "de": "Die Trainingslehre ist der handlungsorientierte Teil der Trainingswissenschaft und beruht vor allem auf Erfahrung (Meisterlehre).",
    "tr": "Trainingslehre, Trainingswissenschaft'ın uygulamaya dönük parçasıdır; deneyime dayanır ve ustadan çırağa aktarılır. Trainingswissenschaft ise araştırmaya dayanır.",
    "en": "Trainingslehre is the practice-oriented part of Trainingswissenschaft; it is based on experience and passed on from master to apprentice. Trainingswissenschaft is based on research."
   },
   {
    "de": "Der Fosbury-Flop ist ein Beispiel für Meisterlehre: Die Technik funktionierte, bevor man sie wissenschaftlich erklären konnte.",
    "tr": "Fosbury sırtüstü atlamayı açıklayamadan kullandı ve kazandı (1968); sebebi sonradan biyomekanik açıkladı: ağırlık merkezi çıtanın altından geçebilir.",
    "en": "Fosbury used the backward jump without being able to explain it and won (1968); biomechanics explained the reason later: the centre of gravity can pass under the bar."
   },
   {
    "de": "Für den Beruf bedeutet die Trainingsdefinition: Ausführung kontrollieren, Fortschritte prüfen und anpassen, Ziele gemeinsam vereinbaren und Über- sowie Unterlastung vermeiden.",
    "tr": "Mesleğe yansıması: uygulamayı kontrol et, ilerlemeyi ölç ve ayarla, hedefi hastayla birlikte koy, ne az ne fazla yükle.",
    "en": "What it means for the job: check the execution, measure and adjust progress, set goals together with the patient, load neither too little nor too much."
   },
   {
    "de": "Das Wort Training stammt vom lateinischen „trahere“ = ziehen, schleppen.",
    "tr": "Kelime Latince „trahere“ (çekmek) kökünden gelir; atların yarış için ahırdan çekilmesi.",
    "en": "The word comes from the Latin root „trahere“ (to pull); horses being pulled out of the stable for a race."
   }
