    "x": "Hipertonus sert, esnek olmayan ve zor kayan dokudur (ör. miyogeloz). Gevşek ve şekil alan doku hipotonus, cansız/tamamen gevşek doku atonus, hamur gibi iz bırakmayan doku ise Quellung'dur.",
    "xEn": "Hypertonus is hard, inelastic tissue that glides poorly (e.g. myogelosis). Slack tissue that takes on shape is hypotonus, lifeless/completely slack tissue is atonus, and doughy tissue that leaves no imprint is Quellung."
