    "x": "Quellung hamur gibidir ama iz bırakmaz (dokunulmaz bölge, Tabuzone); Schwellung'da parmak/çorap izi kalır. Bu ikisini ters çevirmek en sık hatadır; Quellung sert değil hamur kıvamındadır.",
    "xEn": "Quellung is doughy but leaves no imprint (no-touch area, Tabuzone); with Schwellung a finger/sock imprint remains. Swapping these two is the most common mistake; Quellung is not hard but doughy."
