    "x": "Çapraz bulaşma, mikropların bir nesneden diğerine taşınmasıdır (tavuk → kesme tahtası → salata). Hastanede enfekte olmak nozokomiyal enfeksiyon, radyasyona maruz kalmak Exposition, MRSA hastasını izole etmek ise bir koruma önlemidir.",
    "xEn": "Cross-contamination is germs being carried from one object to another (chicken → chopping board → salad). Being infected in hospital is a nosocomial infection, being exposed to radiation is Exposition, isolating an MRSA patient is a protective measure."
