    "xEn": "IfSG § 23 obliges hospitals, doctors' practices and care facilities to follow the recognised hygiene rules. In Germany tap water does not (yet) have to be chlorinated; not throwing medicines in the toilet is a rule related to treatment plants, not the subject of § 23."
