    "x": "Ders tanımı davranışı VE zihinsel süreçleri (Erleben) birlikte kapsar. Sadece gözlemlenebilir davranış eksik bir tanımdır; hastalıkların tedavisi psikiyatriye, grup yaşamı sosyolojiye aittir.",
    "xEn": "The course definition covers behaviour AND mental processes (Erleben) together. Observable behaviour alone is an incomplete definition; treating illnesses belongs to psychiatry, group life to sociology."
