    "x": "Hasta önce sorununu bilmeli (Kognition), sonra buna değip değmeyeceğini tartmalı (Bewertung); ancak ondan sonra ister (Motivation) ve eyleme geçer (Volition). Motivasyon, bilgi ve değerlendirmeden önce gelmez.",
    "xEn": "The patient must first know about the problem (Kognition), then weigh whether it is worth it (Bewertung); only then do they want it (Motivation) and act (Volition). Motivation does not come before knowledge and evaluation."
