    "q": "Nennen und erklären Sie die drei Formen der Prävention mit je einem Beispiel aus der Physiotherapie.",
    "a": "Primärprävention findet vor der Erkrankung statt und soll die Entstehung einer Krankheit verhindern, z. B. regelmäßiges Krafttraining ohne Beschwerden. Sekundärprävention setzt im Frühstadium an und dient der Früherkennung, z. B. Physiotherapie bei beginnenden Rückenschmerzen. Tertiärprävention soll nach einer Erkrankung Verschlechterung, Rückfall und Folgeschäden verhindern, z. B. Reha nach einer Hüft-OP.",
